import { anthropic } from "@ai-sdk/anthropic";
import { streamText, type ModelMessage, stepCountIs } from "ai";
import { SYSTEM_PROMPT } from "./prompt";
import { webToolset } from "./tools";

export function webAgent(messages: ModelMessage[]) {
  return streamText({
    model: anthropic("claude-sonnet-4-5-20250929"),
    system: SYSTEM_PROMPT,
    messages,
    tools: webToolset,
    stopWhen: [stepCountIs(20)],
  });
}

import { ToolSet } from "ai";
import { webSearchTool } from "./web-search";
import { answerQuestionTool } from "./answer-question";
import { deepResearchTool } from "./deep-research";
import { useBrowserTool } from "./use-browser";
import { websetTool } from "./webset";

export const webToolset = {
  web_search: webSearchTool,
  answer_question: answerQuestionTool,
  deep_research: deepResearchTool,
  use_browser: useBrowserTool,
  create_webset: websetTool,
} as ToolSet;

import { InferUITools, UIMessage } from "ai";
import { webToolset } from "./toolset";

type WebTools = InferUITools<typeof webToolset>;

export type WebUIMessage = UIMessage<never, never, WebTools>;

import Exa from "exa-js";
import * as fs from "fs";
import * as path from "path";

export const WEB_AGENT_BASE_DIR = path.join(
  process.cwd(),
  "data",
  "web-agent.local"
);

function ensureDir(dirPath: string) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function safeFileName(input: string) {
  return input.toLowerCase().replace(/[^a-z0-9-_]+/g, "-");
}

export function getExaClient() {
  const exaApiKey = process.env["EXA_API_KEY"];
  if (!exaApiKey) {
    throw new Error("EXA_API_KEY is not set.");
  }
  return new Exa(exaApiKey);
}

export function getAnchorApiKey() {
  const anchorApiKey = process.env["ANCHOR_API_KEY"];
  if (!anchorApiKey) {
    throw new Error("ANCHOR_API_KEY is not set.");
  }
  return anchorApiKey;
}

export function saveArtifact(folder: string, fileName: string, payload: unknown) {
  const dirPath = path.join(WEB_AGENT_BASE_DIR, folder);
  ensureDir(dirPath);

  const fullPath = path.join(dirPath, fileName);
  fs.writeFileSync(fullPath, JSON.stringify(payload, null, 2), "utf8");

  return path.relative(WEB_AGENT_BASE_DIR, fullPath);
}

export function buildTaskMetadata(taskName: string) {
  return {
    task_name: safeFileName(taskName),
    created_at: new Date().toISOString(),
  };
}

import { tool } from "ai";
import { getExaClient } from "./core";
import { webSearchSchema } from "./schema";

export const webSearchTool = tool({
  description: "Search the web for up-to-date information.",
  inputSchema: webSearchSchema,
  execute: async ({ query, allow_cached_results, num_results }) => {
    const exa = getExaClient();
    const { results } = await exa.searchAndContents(query, {
      livecrawl: allow_cached_results ? "fallback" : "preferred",
      numResults: num_results,
      highlights: true,
    });

    return {
      success: true,
      content: results.map((result) => ({
        title: result.title,
        url: result.url,
        content: result.highlights.join("\n"),
        publishedDate: result.publishedDate,
      })),
    };
  },
});

import { tool } from "ai";
import { getExaClient } from "./core";
import { answerQuestionSchema } from "./schema";

export const answerQuestionTool = tool({
  description: "Answer a question using web sources.",
  inputSchema: answerQuestionSchema,
  execute: async ({ question, output_schema }, { toolCallId }) => {
    const exa = getExaClient();
    const response = await exa.answer(question, {
      outputSchema: output_schema ? JSON.parse(output_schema) : undefined,
    });

    console.log({
      type: "exa.answer",
      tool_call_id: toolCallId,
      request_id: response.requestId,
      cost_dollars: response.costDollars,
    });

    return {
      success: true,
      answer: response.answer,
      citations: response.citations,
    };
  },
});

import { tool } from "ai";
import { buildTaskMetadata, getExaClient, saveArtifact } from "./core";
import { deepResearchSchema } from "./schema";

export const deepResearchTool = tool({
  description: "Create a deep research task.",
  inputSchema: deepResearchSchema,
  execute: async ({ task_name, instructions, tier, output_schema }) => {
    const exa = getExaClient();

    const researchTask = await exa.research.create({
      instructions,
      model: tier === "pro" ? "exa-research-pro" : "exa-research",
      outputSchema: output_schema ? JSON.parse(output_schema) : undefined,
    });

    const relativePath = saveArtifact("research-tasks", `${researchTask.researchId}.json`, {
      type: "research-task",
      id: researchTask.researchId,
      provider: "exa",
      name: task_name,
      data: researchTask,
      metadata: buildTaskMetadata(task_name),
    });

    return {
      success: true,
      message: "Research task created.",
      artifact_path: relativePath,
      task_id: researchTask.researchId,
    };
  },
});

import { tool } from "ai";
import { getAnchorApiKey, saveArtifact } from "./core";
import { useBrowserSchema } from "./schema";
import {
  connectToAnchorSession,
  endAnchorSession,
  startAnchorSession,
} from "./services/anchor";

export const useBrowserTool = tool({
  description: "Start a browser session and execute web tasks using Anchor Browser.",
  inputSchema: useBrowserSchema,
  execute: async ({ task, initialUrl }) => {
    const anchorApiKey = getAnchorApiKey();
    const session = await startAnchorSession(anchorApiKey, {
      initialUrl,
      headless: false,
    });

    try {
      const browser = await connectToAnchorSession(anchorApiKey, session.id);
      const context = browser.contexts()[0];
      const page = context.pages()[0];
      await page.goto(initialUrl, { waitUntil: "domcontentloaded" });

      const ai = context.serviceWorkers()[0];
      const result = await ai.evaluate(task);

      const sessionPayload = {
        type: "browser-session",
        sessionId: session.id,
        cdpUrl: session.cdp_url,
        liveViewUrl: session.live_view_url,
        task,
        initialUrl,
        headless: false,
        createdAt: new Date().toISOString(),
        result,
        status: "completed",
      };

      const relativePath = saveArtifact("browser", `${session.id}.browser.json`, sessionPayload);

      await browser.close();
      await endAnchorSession(anchorApiKey, session.id);

      return {
        success: true,
        result,
        artifact_path: relativePath,
        message: `Browser task completed. Live view: ${session.live_view_url}`,
      };
    } catch (error) {
      await endAnchorSession(anchorApiKey, session.id);

      return {
        success: false,
        error: `Error executing browser task: ${(error as Error)?.message || error}`,
      };
    }
  },
});

import { tool } from "ai";
import { buildTaskMetadata, getExaClient, saveArtifact } from "./core";
import { createWebsetSchema } from "./schema";

export const websetTool = tool({
  description: "Create a webset (entity list + enrichments) from user instructions.",
  inputSchema: createWebsetSchema,
  execute: async ({
    task_name,
    instructions,
    num_results,
    entity_type,
    custom_entity_description,
    enrichments,
  }) => {
    const exa = getExaClient();

    const webset = await exa.websets.create({
      search: {
        query: instructions,
        count: num_results,
        entity: entity_type
          ? entity_type === "custom"
            ? custom_entity_description
              ? { type: "custom", description: custom_entity_description }
              : undefined
            : { type: entity_type }
          : undefined,
      },
      enrichments: enrichments.map((item) => ({
        description: item.description,
      })),
    });

    const relativePath = saveArtifact("websets", `${webset.id}.json`, {
      type: "webset",
      id: webset.id,
      provider: "exa",
      name: task_name,
      data: webset,
      metadata: buildTaskMetadata(task_name),
    });

    return {
      success: true,
      message: "Webset created.",
      artifact_path: relativePath,
      webset_id: webset.id,
    };
  },
});

import { chromium, type Browser } from "playwright-core";

const ANCHOR_BASE_URL = "https://api.anchorbrowser.io/v1";

export interface AnchorBrowserSession {
  id: string;
  cdp_url: string;
  live_view_url: string;
}

export interface StartAnchorSessionConfig {
  initialUrl?: string;
  headless?: boolean;
  timeout?: {
    maxDuration: number;
    idleTimeout: number;
  };
}

export async function startAnchorSession(
  apiKey: string,
  config: StartAnchorSessionConfig
): Promise<AnchorBrowserSession> {
  const response = await fetch(`${ANCHOR_BASE_URL}/sessions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "anchor-api-key": apiKey,
    },
    body: JSON.stringify({
      session: {
        recording: { active: true },
        timeout: config.timeout ?? {
          max_duration: 10,
          idle_timeout: 5,
        },
        live_view: { read_only: true },
      },
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(
      `Failed to start Anchor Browser session: ${response.status} ${response.statusText} - ${error}`
    );
  }

  const data = await response.json();
  return data.data as AnchorBrowserSession;
}

export async function endAnchorSession(
  apiKey: string,
  sessionId: string
): Promise<void> {
  const response = await fetch(`${ANCHOR_BASE_URL}/sessions/${sessionId}`, {
    method: "DELETE",
    headers: {
      "anchor-api-key": apiKey,
    },
  });

  if (!response.ok) {
    throw new Error(
      `Failed to end session: ${response.status} ${response.statusText}`
    );
  }
}

export async function connectToAnchorSession(
  apiKey: string,
  sessionId: string
): Promise<Browser> {
  const cdpUrl = `wss://connect.anchorbrowser.io?apiKey=${apiKey}&sessionId=${sessionId}`;
  return chromium.connectOverCDP(cdpUrl);
}
